mapper.select:
/* User05Mapper.countUserSiteAuth */
SELECT COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* User05Mapper.selectDailyUserList */
WITH RECURSIVE search_node_tree AS ( SELECT N.CMPNY_CD, N.SITE_CD, N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.NODE_CD = #{nodeCd}
AND N.SITE_CD = #{siteCd}
UNION ALL
SELECT C.CMPNY_CD, C.SITE_CD, C.NODE_CD FROM TB_SITE_NODE C INNER JOIN search_node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT H.HIS_ID AS hisId
, D.USER_CD AS userCd , H.SITE_CD AS siteCd , CASE WHEN D.USER_NM IS NULL OR D.USER_NM = '' THEN '-' ELSE D.USER_NM END AS userNm , D.MBL_NO_ENC AS mblNoEnc , FNC_CMM_INFO_SRCH(H.CMPNY_CD, 'SITE', H.SITE_CD, NULL) AS siteNm , CASE WHEN U.NODE_CD IS NULL OR U.NODE_CD = '' THEN '-' ELSE FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'NODE', U.SITE_CD, U.NODE_CD) END AS nodeNm , H.SLOT_NO AS slotNo , DATE_FORMAT(H.OCCUPY_DTIME, '%Y-%m-%d %H:%i:%s') AS occupyDtime , DATE_FORMAT(H.RELEASE_DTIME, '%Y-%m-%d %H:%i:%s') AS releaseDtime FROM TB_DAILY_USER_SLOT_HIS H LEFT OUTER JOIN TB_DAILY_USER D ON ( H.CMPNY_CD = D.CMPNY_CD AND H.USER_ID = D.USER_ID ) LEFT OUTER JOIN TB_USER U ON ( D.CMPNY_CD = U.CMPNY_CD AND D.USER_CD = U.USER_CD ) WHERE H.CMPNY_CD = #{gvCmpnyCd}
AND H.SITE_CD IN ( SELECT SA.SITE_CD FROM TB_USER_SITE_AUTH SA WHERE SA.CMPNY_CD = #{gvCmpnyCd} AND SA.USER_CD = #{gvUserCd} AND SA.USE_YN = 'Y' )
AND H.SITE_CD = #{siteCd}
AND U.NODE_CD IN (SELECT T.NODE_CD FROM search_node_tree T)
AND U.NODE_CD = #{nodeCd}
AND D.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND D.MBL_NO_HMAC = #{mblNoHmac}
AND D.MBL_NO_LAST4 = #{mblNoLast4}
AND H.OCCUPY_DTIME >= STR_TO_DATE(CONCAT(#{occupyFrom}, ' 00:00:00'), '%Y-%m-%d %H:%i:%s')
AND H.OCCUPY_DTIME <= STR_TO_DATE(CONCAT(#{occupyTo}, ' 23:59:59'), '%Y-%m-%d %H:%i:%s')
ORDER BY H.OCCUPY_DTIME DESC, H.HIS_ID DESC LIMIT #{limit} OFFSET #{offset}

/* User05Mapper.selectDailyUserSiteCd */
SELECT D.SITE_CD
FROM TB_DAILY_USER D
WHERE D.CMPNY_CD = #{cmpnyCd}
  AND D.USER_CD = #{userCd}
LIMIT 1
